/** Real create/end originals and genuine raw revisions, read from the recovered package. */
function recoveryAssignmentOriginal(PDO $db,array $tariff):array
{
    $actor='own-tariff-recovery-admin';$registry=new \Kulturhus\Verein\Registry($db,$actor);$person=$registry->saveContact(null,0,'person','Own original recovery assigned contact 0','assignment-recovery@example.invalid','Own unchanged original address',['birthday'=>'2000-01-01']);
    $requests=new \Kulturhus\Verein\Settings\AssignmentRequests($db,$actor);$repo=new \Kulturhus\Verein\Settings\AssignmentRepository($db,$actor);
    $input=['operation'=>'create','tab'=>'services','id'=>'','version'=>'0','data'=>['catalog_id'=>$tariff['ids']['service'],'contact_id'=>$person,'start'=>'2030-01-01','end'=>'']];$plan=$requests->prepare($input);$first=$requests->accept($input,bin2hex(random_bytes(16)),$plan['hash'],true);$id=$first['result']['id'];$revision=$repo->revision($id,'services','1');
    $end=['operation'=>'end','tab'=>'services','id'=>$id,'version'=>'1','data'=>['end'=>'2030-12-31']];$plan=$requests->prepare($end);$ended=$requests->accept($end,bin2hex(random_bytes(16)),$plan['hash'],true);
    return['originals'=>[$first,$ended],'current'=>$repo->state($id,'services'),'first_revision'=>$revision,'end_revision'=>$repo->revision($id,'services','2'),'quote'=>(new \Kulturhus\Verein\CatalogPricing($db,$actor))->quote($id,'2030-01-20'),'earlier_entry'=>$tariff['entry']];
}
